import re
from datetime import datetime

_DIGITS = frozenset("0123456789")
_GMAIL_DOMAINS = frozenset({"gmail.com", "googlemail.com"})
_UPDATED_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")


def _all_digits(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _normalize_email(raw):
    """Rule 1: extract angle-bracket address, strip, lowercase, canonicalize gmail."""
    s = (raw or "").strip()
    m = re.search(r"<([^<>]*)>", s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _clean_email(raw):
    """Rule 2: return the normalized email if valid, else ""."""
    s = _normalize_email(raw)
    if s.count("@") != 1:
        return ""
    local, domain = s.split("@")
    if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
        return ""
    return s


def _normalize_phone(raw):
    """Rule 3: return the normalized 10-digit phone if valid, else ""."""
    s = (raw or "").lower()
    cuts = [i for i in (s.find(marker) for marker in ("x", "ext", "#")) if i != -1]
    if cuts:
        s = s[:min(cuts)]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _normalize_zip(raw):
    """Rule 4: return a 5-digit ZIP or ""."""
    z = (raw or "").strip()
    m = re.fullmatch(r"([0-9]+)-[0-9]{4}", z)  # ZIP+4 form, e.g. 02139-4307
    if m:
        z = m.group(1)
    if len(z) == 4 and _all_digits(z):  # Excel ate the leading zero
        z = "0" + z
    if len(z) == 5 and _all_digits(z):
        return z
    return ""


def _normalize_name(raw):
    """Rule 5: strip, and title-case if entirely upper- or lower-case."""
    s = (raw or "").strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw, index):
    """Rule 6: parse updated into a datetime (date-only means midnight)."""
    s = (raw or "").strip()
    for fmt in _UPDATED_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"row {index}: unrecognized updated value {raw!r}")


def _is_opted_out(raw):
    """Rule 7."""
    return (raw or "").strip().lower() in {"y", "yes", "true", "1"}


def _normalize_tags(raw):
    """Rule 8: split on ';' or ',', strip, lowercase, drop empties, return a set."""
    parts = re.split(r"[;,]", raw or "")
    return {p.strip().lower() for p in parts} - {""}


def _pick(group, field):
    """Rule 11 selection: manual rows first, then latest updated, then earliest row."""
    cands = [r for r in group if r[field]]
    if not cands:
        return ""
    # Group rows are already in input order. Stable sorts preserve that order for ties.
    cands.sort(key=lambda r: r["updated"], reverse=True)
    cands.sort(key=lambda r: not r["manual"])
    return cands[0][field]


def _merge_group(group):
    tags = set()
    for r in group:
        tags |= r["tags"]
    return {
        "first_name": _pick(group, "first_name"),
        "last_name": _pick(group, "last_name"),
        "zip": _pick(group, "zip"),
        "email": _pick(group, "email"),
        "phone": _pick(group, "phone"),
        "source": _pick(group, "source"),
        "tags": ";".join(sorted(tags)),
        "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
        "updated": max(r["updated"] for r in group).strftime("%Y-%m-%d"),
    }


def dedupe_contacts(rows):
    # Normalize each row and drop rows with no valid email or phone (rule 9).
    records = []
    for idx, row in enumerate(rows):
        email = _clean_email(row.get("email"))
        phone = _normalize_phone(row.get("phone"))
        if not email and not phone:
            continue
        source = (row.get("source") or "").strip().lower()
        records.append({
            "index": idx,
            "first_name": _normalize_name(row.get("first_name")),
            "last_name": _normalize_name(row.get("last_name")),
            "zip": _normalize_zip(row.get("zip")),
            "email": email,
            "phone": phone,
            "source": source,
            "manual": source == "manual",
            "tags": _normalize_tags(row.get("tags")),
            "opted_out": _is_opted_out(row.get("opted_out")),
            "updated": _parse_updated(row.get("updated"), idx),
        })

    # Union-find: rows sharing a match key are the same person (rule 10, transitive).
    parent = list(range(len(records)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    key_owner = {}
    for pos, rec in enumerate(records):
        keys = []
        if rec["email"]:
            keys.append(("email", rec["email"]))
        if rec["phone"] and rec["last_name"]:
            keys.append(("phone+last", rec["phone"], rec["last_name"].casefold()))
        for key in keys:
            if key in key_owner:
                union(pos, key_owner[key])
            else:
                key_owner[key] = pos

    # Collect groups in order of their earliest input row (rule 12).
    groups = {}
    order = []
    for pos, rec in enumerate(records):
        root = find(pos)
        if root not in groups:
            groups[root] = []
            order.append(root)
        groups[root].append(rec)

    return [_merge_group(groups[root]) for root in order]
